async function applyNumFix() {
  const page = await node('144:2'); await figma.setCurrentPageAsync(page);
  const dpage = figma.root.children.find(p => p.name === DETAIL_PAGE); await dpage.loadAsync();
  const texts = [page, dpage].flatMap(p => p.findAll(n => n.type === 'TEXT'));
  let changed = 0; const missing = [];
  for (const [oldMd, newMd] of NUMFIX) {
    const want = parse(oldMd).out, hits = texts.filter(t => t.characters === want);
    if (!hits.length) { if (!texts.some(t => t.characters === parse(newMd).out)) missing.push(want.split('\n')[0].slice(0, 18)); continue; }
    for (const t of hits) { await richKeep(t, newMd); changed++; }
  }
  return (changed ? '수치 문장 ' + changed + '곳 수정' : '수치 문장은 이미 반영됨') + (missing.length ? ' · 손으로 고쳐 건너뜀: ' + missing.join(', ') : '');
}
// Application copies per company (BR is set by build_plugin.py). Only the copies change: two resume pages
// next to resume v4 and one portfolio section below the combined portfolio. Originals are never touched.
// Copies are made once; re-running only re-applies colors and order, so hand edits in the copies stay.
const near = (c, h) => Math.abs(c.r - h.r) < 0.01 && Math.abs(c.g - h.g) < 0.01 && Math.abs(c.b - h.b) < 0.01;
const isAccent = c => near(c, OR) || near(c, BR.text);
const solidAccent = fills => Array.isArray(fills) && fills.some(f => f.type === 'SOLID' && isAccent(f.color));

// accent text -> navy; accent text that is not a link also gets a yellow highlighter behind it
async function brandText(t) {
  const segs = t.getStyledTextSegments(['fills', 'hyperlink', 'fontSize']).filter(s => solidAccent(s.fills));
  if (!segs.length) return 0;
  for (const s of segs) t.setRangeFills(s.start, s.end, [{ type: 'SOLID', color: BR.text }]);   // color needs no font
  // short phrases get a highlighter; a long sentence gets a thin yellow underline so two lines don't read as a block
  const short = s => s.characters.replace(/\s/g, '').length <= 18;
  const marks = segs.filter(s => !s.hyperlink && s.characters.trim());
  if (!marks.length) return segs.length;
  await loadNodeFonts(t);   // decoration needs the node's fonts
  for (const s of marks) {
    const th = short(s) ? Math.round(s.fontSize * 0.4) : Math.max(2, Math.round(s.fontSize * 0.16));
    const off = short(s) ? -Math.round(s.fontSize * 0.26) : 2;
    t.setRangeTextDecoration(s.start, s.end, 'UNDERLINE');
    t.setRangeTextDecorationColor(s.start, s.end, { value: { type: 'SOLID', color: short(s) ? BR.mark : BR.line } });
    t.setRangeTextDecorationThickness(s.start, s.end, { unit: 'PIXELS', value: th });
    t.setRangeTextDecorationOffset(s.start, s.end, { unit: 'PIXELS', value: off });
    t.setRangeTextDecorationSkipInk(s.start, s.end, false);
  }
  return segs.length;
}
// blue lines -> yellow (1-2px side lines become 3px so yellow is visible); blue icons -> navy
function brandShapes(root) {
  let n = 0;
  for (const x of root.findAll(() => true)) {
    if (x.type === 'TEXT') continue;
    if ('strokes' in x && solidAccent(x.strokes)) {
      x.strokes = x.strokes.map(f => f.type === 'SOLID' && isAccent(f.color) ? Object.assign({}, f, { color: BR.line }) : f);
      if (x.strokeWeight === figma.mixed && x.strokeLeftWeight > 0 && x.strokeLeftWeight < 3) x.strokeLeftWeight = 3;
      n++;
    }
    if (x.type === 'VECTOR' && solidAccent(x.fills)) { x.fills = x.fills.map(f => f.type === 'SOLID' ? Object.assign({}, f, { color: BR.text }) : f); n++; }
  }
  return n;
}
async function brandStyle(root) {
  let t = 0; const skipped = [];
  for (const x of root.findAll(n => n.type === 'TEXT')) { try { t += await brandText(x); } catch (e) { skipped.push(x.characters.slice(0, 10)); } }
  if (skipped.length) KSKIP.push(...skipped);
  return { text: t, shapes: brandShapes(root) };
}
const KSKIP = [];   // texts whose fonts could not be loaded on this computer
// set text keeping the node's regular style; **x** = bold navy with highlighter
async function brandRich(t, md) {
  await loadNodeFonts(t); const seg = t.getStyledTextSegments(['fontName', 'fills']).find(s => s.fontName.style !== 'Bold');
  await figma.loadFontAsync(P('Bold'));
  const { out, ranges } = parse(md); t.characters = out;
  t.setRangeFontName(0, out.length, seg.fontName); t.setRangeFills(0, out.length, seg.fills); t.setRangeTextDecoration(0, out.length, 'NONE');
  for (const r of ranges) { t.setRangeFontName(r.st, r.en, P('Bold')); t.setRangeFills(r.st, r.en, [{ type: 'SOLID', color: OR }]); }
  await brandText(t);
}
const hasText = (n, s) => !!n.findOne(x => x.type === 'TEXT' && x.characters.includes(s));

async function applyBrandResume() {
  const page = await node('375:4'); await figma.setCurrentPageAsync(page);
  const rep = [];
  let k1 = page.children.find(c => c.name === BR.r1), k2 = page.children.find(c => c.name === BR.r2);
  if (!k1 || !k2) {
    const v1 = page.children.find(c => c.name === V4.p1), v2 = page.children.find(c => c.name === V4.p2);
    if (!v1 || !v2) throw new Error('resume_v4가 없습니다');
    if (!k1) { k1 = v1.clone(); k1.name = BR.r1; k1.x = v1.x + 994 * BR.col; k1.y = v1.y; page.appendChild(k1); rep.push('1장 사본 생성'); }
    if (!k2) { k2 = v2.clone(); k2.name = BR.r2; k2.x = v2.x + 994 * BR.col; k2.y = v2.y; page.appendChild(k2); rep.push('2장 사본 생성'); }
  }
  // 1. 디딤로그 (data collection) before A&I.com
  const rows = k1.children.filter(c => c.name === 'Row');
  const ai = rows.find(r => hasText(r.children[0], 'A&I')), didim = rows.find(r => hasText(r.children[0], '디딤로그'));
  if (BR.didimFirst && ai && didim && k1.children.indexOf(didim) > k1.children.indexOf(ai)) {
    const div = k1.children[k1.children.indexOf(didim) - 1];
    k1.insertChild(k1.children.indexOf(ai), didim); k1.insertChild(k1.children.indexOf(ai), div);
    rep.push('디딤로그를 맨 앞으로');
  }
  // 2. SoloPlay: put the place-data line back, before the AI line
  const solo = k2.children.find(c => c.name === 'Row' && hasText(c.children[0], 'SoloPlay'));
  if (BR.soloPlace && solo && !hasText(solo, 'Kakao Local')) {
    const list = solo.findOne(n => n.name === 'BulletList'), first = list.children[0], b = first.clone();
    list.insertChild(0, b);
    const t = b.findAll(n => n.type === 'TEXT' && n.characters.trim().length > 1)[0];
    await brandRich(t, 'Kakao Local API 검색 결과를 **장소 ID 기준으로 중복 없이** 정리해,\nMongoDB에 장소부터 먼저 저장했습니다.');
    rep.push('SoloPlay 장소 데이터 줄 추가');
  }
  // 3. Problem Solving right after Skills (CS basics in the posting's requirements)
  const kids = k2.children, skills = kids.find(c => c.name === 'SecHead' && hasText(c, 'Skills'));
  const ps = ['PS · divider', 'PS · SubSec', 'PS · Row'].map(n => kids.find(c => c.name === n));
  if (skills && ps.every(Boolean)) {
    const at = kids.indexOf(skills) + 2;   // SecHead, BulletList, then PS
    if (kids.indexOf(ps[0]) !== at) { ps.slice().reverse().forEach(p => k2.insertChild(at, p)); rep.push('Problem Solving을 Skills 바로 아래로'); }
  }
  const s1 = await brandStyle(k1), s2 = await brandStyle(k2);
  rep.push('강조 ' + (s1.text + s2.text) + '곳 ' + BR.colorName, overflowReport(k1), overflowReport(k2));
  if (KSKIP.length) rep.push('글꼴이 없어 밑줄 못 넣음: ' + KSKIP.join(', '));
  return BR.label + ' 이력서 사본: ' + rep.join(' · ');
}

// Figma image hash = SHA-1 of the bytes; these are the blue images the portfolio was built with
const BLUE_HASH = {
  '35addbf6f416aefd2f1ac12ba8f75282e1a7d1b2': 'arch', '71e76e75a02d2088f10baf9fb0fd3f92ceab86ad': 'batch', '870e50bc2a1dd9446076b52adcad2465e7ab3635': 'bot',
  '3cf75af8baf9f0ea538e2c214c643af3394e32da': 'didim-admin', 'e139ee2179c03bf302faf3b96c6a96f14eb37c66': 'didim-collect', '05551e689b7da6ad5d3036a08bc6475a0844dc08': 'didim-intro',
  '1d21e715a326284c04b22043c7ec21fda2aa3f55': 'didim-split', '5dfc90a665b8f274c8ef18c41c466065028a73f2': 'ev', 'a64555618355c13b977f7de85380f8317f1b0b8d': 'gozzi',
  'e5036d90d2fc6cb07f4a07de15fe31660d47bae2': 'gw', '2533932436a4b60bdc1c54d62d63dbc8588e0e1d': 'invest', '90dc4e6b7f462f4501357ac604b3fb728cb80363': 'soloplay',
  'd687ea8aef1e7c33d175ac99ad92c266a5414af1': 'tests',
};
// Kakao order: cover, 디딤로그 (04a 04 04b 04c), A&I (02 02a 03 03a 03b 03c), 05 06 07
const KAKAO_ORDER = ['01', '04a', '04', '04b', '04c', '02', '02a', '03', '03a', '03b', '03c', '05', '06', '07'];

async function applyBrandPortfolio() {
  const page = await node('144:2'); await figma.setCurrentPageAsync(page);
  const src = page.children.find(c => c.name === COMBINED); if (!src) throw new Error('통합 섹션이 없습니다');
  const rep = [];
  let sec = page.children.find(c => c.name === BR.pf);
  if (!sec) { sec = src.clone(); sec.name = BR.pf; sec.x = src.x; sec.y = src.y + (src.height + 400) * BR.col; page.appendChild(sec); rep.push('사본 생성'); }
  // images: swap each blue image for its Kakao version
  const kh = {}; let img = 0; const BIMAGES = KIMAGES;
  for (const n of sec.findAll(x => 'fills' in x && Array.isArray(x.fills) && x.fills.some(f => f.type === 'IMAGE'))) {
    const fills = n.fills.map(f => {
      const key = f.type === 'IMAGE' && BLUE_HASH[f.imageHash]; if (!key) return f;
      if (!kh[key]) kh[key] = figma.createImage(figma.base64Decode(BIMAGES[key])).hash;
      img++; return Object.assign({}, f, { imageHash: kh[key] });
    });
    n.fills = fills;
  }
  rep.push('그림 ' + img + '장 교체');
  // order and page numbers
  const frames = sec.children.filter(f => /^Portfolio \d\d · /.test(f.name)), key = f => f.name.split(' · ')[1];
  const xs = [...new Set(frames.map(f => f.x))].sort((a, b) => a - b), ys = [...new Set(frames.map(f => f.y))].sort((a, b) => a - b);
  if (BR.order && frames.length === KAKAO_ORDER.length && frames.find(f => key(f) === '04a').name.slice(10, 12) !== '02') {
    for (const f of frames) {
      const i = KAKAO_ORDER.indexOf(key(f)); if (i < 0) throw new Error('모르는 장 ' + f.name);
      const no = String(i + 1).padStart(2, '0');
      f.name = 'Portfolio ' + no + ' · ' + key(f); f.x = xs[i % xs.length]; f.y = ys[Math.floor(i / xs.length)];
      const pn = f.findOne(t => t.type === 'TEXT' && /^\d\d \/ 14$/.test(t.characters));
      if (pn) { await loadNodeFonts(pn); pn.characters = no + ' / 14'; }
    }
    frames.slice().sort((a, b) => a.name.localeCompare(b.name)).forEach((f, i) => sec.insertChild(i, f));   // layer order = page order for export
    // cover index: 디딤로그 row first, page ranges follow the new order
    const cover = frames.find(f => key(f) === '01');
    const rowOf = s => { let r = cover.findOne(x => x.type === 'TEXT' && x.characters === s); while (r && r.layoutMode !== 'HORIZONTAL') r = r.parent; return r; };
    const aiRow = rowOf('A&I.com'), dRow = rowOf('디딤로그');
    if (aiRow && dRow && aiRow.parent === dRow.parent) aiRow.parent.insertChild(aiRow.parent.children.indexOf(aiRow), dRow);
    for (const [row, from, to] of [[aiRow, '02-07', '06-11'], [dRow, '08-11', '02-05']]) {
      const t = row && row.findOne(x => x.type === 'TEXT' && x.characters === from); if (t) { await loadNodeFonts(t); t.characters = to; }
    }
    rep.push('디딤로그를 표지 바로 뒤로');
  }
  const s = await brandStyle(sec);
  rep.push('강조 글자 ' + s.text + '곳 · 선·아이콘 ' + s.shapes + '곳');
  if (KSKIP.length) rep.push('글꼴이 없어 밑줄 못 넣음: ' + KSKIP.join(', '));
  return BR.label + ' 포트폴리오 사본: ' + rep.join(' · ');
}
const IMAGES = {};
const KIMAGES = {"arch": "", "ev": "", "batch": "", "gw": "", "bot": "", "tests": "", "didim-intro": "", "didim-collect": "", "didim-admin": "", "didim-split": "", "soloplay": "", "gozzi": "", "invest": ""};
const BR = { label: "네이버웹툰", r1: "naver_resume_01", r2: "naver_resume_02", pf: "네이버웹툰 · 포트폴리오", col: 2, colorName: "짙은 초록·초록", text: { r: 0x00 / 255, g: 0x6B / 255, b: 0x35 / 255 }, mark: { r: 0xA6 / 255, g: 0xF3 / 255, b: 0xC9 / 255 }, line: { r: 0x00 / 255, g: 0xDC / 255, b: 0x64 / 255 }, didimFirst: false, soloPlace: false, order: false };

(async () => {
  try {
    const pages = figma.root.children.map(p=>p.id);
    // this build makes the application copies for one company (BR); originals and hand edits stay as they are
    if (pages.includes('375:4')) { figma.closePlugin('완료: ' + await applyBrandResume()); return; }
    if (!pages.includes('144:2')) throw new Error('이 파일은 대상이 아닙니다');
    const pg = figma.root.children.find(x => x.id === '144:2'); await pg.loadAsync();
    if (!pg.children.some(c => c.name === COMBINED)) throw new Error('통합 섹션이 없습니다');
    const nf = await applyNumFix();
    figma.closePlugin('완료: ' + nf + ' · ' + await applyBrandPortfolio());
  } catch (e) {
    figma.closePlugin('실패: ' + (e && e.message ? e.message : String(e)));
  }
})();
